-- No source issuance, economic fact, runtime grant, new role or generic DDL.
begin;
do $preflight$declare f record;actual_readers text[];begin
 if not exists(select 1 from pg_roles where rolname='world_v2_industry_source_owner'and not(rolcanlogin or rolsuper or rolbypassrls or rolcreatedb or rolcreaterole or rolreplication))or has_schema_privilege('world_v2_industry_source_owner','world_v2','CREATE')then raise exception 'PROPOSAL_UPGRADE_EXACT_OWNER_REQUIRED'using errcode='42501';end if;
 if not exists(select 1 from pg_class c where c.oid=to_regclass('world_v2.postwar_industry_utility_source')and c.relkind='r'and pg_get_userbyid(c.relowner)='world_v2_industry_source_owner'and c.relrowsecurity and c.relforcerowsecurity)then raise exception 'PROPOSAL_UPGRADE_EXISTING_FORCED_RLS_REQUIRED'using errcode='55000';end if;
 select p.*,pg_get_function_result(p.oid)as result,pg_get_userbyid(p.proowner)as owner_name into f from pg_proc p where p.oid=to_regprocedure('world_v2.publish_postwar_industry_utility_source(text,text,jsonb,text)');
 if not found or f.proisstrict or f.proleakproof or f.proparallel<>'u'or f.pronargdefaults<>0 or pg_get_expr(f.proargdefaults,0)is distinct from null or f.owner_name<>'world_v2_industry_source_owner'or not f.prosecdef or f.prokind<>'f'or f.provolatile<>'v'or not f.proretset or f.proconfig is distinct from array['search_path=pg_catalog']::text[]or f.proargnames is distinct from array['p_world','p_source','p_raw','p_adoption','source_ref','source_sha256']::text[]or f.result<>'TABLE(source_ref text, source_sha256 text)'or f.prolang<>(select oid from pg_language where lanname='plpgsql')or encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')<>'f10e860aff97e8877a580a50521f6a0806895b7824ed36ae27330a974dc4b0ed'then raise exception 'PROPOSAL_UPGRADE_EXACT_OLD_FUNCTION_REQUIRED'using errcode='55000';end if;
 if exists(select 1 from aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))x where x.grantee=0 or x.privilege_type<>'EXECUTE'or x.is_grantable)then raise exception 'PROPOSAL_UPGRADE_EXACT_FUNCTION_ACL_REQUIRED'using errcode='42501';end if;
 select coalesce(array_agg(pg_get_userbyid(x.grantee)::text order by pg_get_userbyid(x.grantee)::text),array[]::text[])into actual_readers from aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))x where x.grantee<>f.proowner;
 if actual_readers is distinct from array['world_v2_industry_source_publisher']::text[]then raise exception 'PROPOSAL_UPGRADE_EXACT_FUNCTION_ACL_REQUIRED'using errcode='42501';end if;
 select p.*,pg_get_function_result(p.oid)as result,pg_get_userbyid(p.proowner)as owner_name into f from pg_proc p where p.oid=to_regprocedure('world_v2.read_postwar_industry_water_command_evidence(text,text,text,text,bigint,bigint,text,text,jsonb)');
 if not found or f.proisstrict or f.proleakproof or f.proparallel<>'u'or f.pronargdefaults<>0 or pg_get_expr(f.proargdefaults,0)is distinct from null or f.owner_name<>'world_v2_industry_source_owner'or not f.prosecdef or f.prokind<>'f'or f.provolatile<>'v'or not f.proretset or f.proconfig is distinct from array['search_path=pg_catalog']::text[]or f.proargnames is distinct from array['p_world','p_country','p_facility','p_run','p_before_version','p_before_sequence','p_until','p_work_fingerprint','p_power_fingerprints','grant_pin','power_pins','work_source','protected_claims','from_ticks']::text[]or f.result<>'TABLE(grant_pin jsonb, power_pins jsonb, work_source jsonb, protected_claims jsonb, from_ticks text)'or f.prolang<>(select oid from pg_language where lanname='plpgsql')or encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')<>'544d8693de6a08368a4590d2ea88f87ca43e9003e02091fe2e3f18a9dbd442ca'then raise exception 'PROPOSAL_UPGRADE_EXACT_OLD_FUNCTION_REQUIRED'using errcode='55000';end if;
 if exists(select 1 from aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))x where x.grantee=0 or x.privilege_type<>'EXECUTE'or x.is_grantable)then raise exception 'PROPOSAL_UPGRADE_EXACT_FUNCTION_ACL_REQUIRED'using errcode='42501';end if;
 select coalesce(array_agg(pg_get_userbyid(x.grantee)::text order by pg_get_userbyid(x.grantee)::text),array[]::text[])into actual_readers from aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))x where x.grantee<>f.proowner;
 if actual_readers is distinct from array['world_v2_industry_source_reader']::text[]then raise exception 'PROPOSAL_UPGRADE_EXACT_FUNCTION_ACL_REQUIRED'using errcode='42501';end if;
